const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const pick = (...keys) => {
  for (const k of keys) {
    if (raw[k] !== undefined && raw[k] !== null && String(raw[k]).trim() !== '') {
      return String(raw[k]).trim();
    }
  }
  return '';
};

const email = pick('email', 'work_email', 'Email').toLowerCase();
if (!email || !email.includes('@')) {
  throw new Error('Valid email missing in form submission');
}

const name = pick('name', 'full_name', 'fullName', 'Name') ||
  [pick('first_name', 'firstName'), pick('last_name', 'lastName')].filter(Boolean).join(' ');

const domain = email.split('@')[1];
const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'icloud.com', 'proton.me', 'protonmail.com'];

return {
  json: {
    name,
    email,
    phone: pick('phone', 'phone_number', 'Phone'),
    company: pick('company', 'company_name', 'Company'),
    message: pick('message', 'Message', 'notes'),
    source: pick('source', 'utm_source', 'platform') || 'website',
    domain,
    isFreeEmail: freeDomains.includes(domain),
    receivedAt: new Date().toISOString()
  }
};

let lead;
try {
  lead = $('Normalize Lead').item.json;
} catch (err) {
  lead = $('Normalize Lead').first().json;
}

const enrich = $json || {};
const person = enrich.person || {};
const company = enrich.company || {};
const employment = person.employment || {};
const title = employment.title || '';
const seniority = employment.seniority || '';
const employees = (company.metrics && company.metrics.employees) || 0;
const enriched = !!(person.id || company.id);

// ---- Lead scoring ----
let score = 0;
if (!lead.isFreeEmail) score += 20;                       // business email
if (lead.phone) score += 10;                              // phone diya
if (lead.message && lead.message.length > 50) score += 10; // detailed message
if (company.name || lead.company) score += 10;            // company known
if (/\b(budget|quote|pricing|proposal|hire|urgent|asap|project|website|app|automation|erp|crm)\b/i.test(lead.message || '')) score += 15; // buying intent
if (employees >= 50) score += 20; else if (employees >= 10) score += 10; // company size
if (/executive|director|vp/i.test(seniority) || /ceo|founder|owner|cto|coo|head|director|vp/i.test(title)) score += 30; // decision maker
score = Math.min(score, 100);

const HOT = 60;   // <-- threshold yahan change karo
const WARM = 35;
const tier = score >= HOT ? 'HOT' : (score >= WARM ? 'WARM' : 'COLD');

return {
  json: {
    ...lead,
    companyName: company.name || lead.company || '',
    industry: (company.category && company.category.industry) || '',
    employees,
    title,
    seniority,
    linkedin: (person.linkedin && person.linkedin.handle) ? 'https://linkedin.com/' + person.linkedin.handle : '',
    country: (company.geo && company.geo.country) || (person.geo && person.geo.country) || '',
    enriched,
    score,
    tier,
    isHighValue: score >= HOT
  }
};

